const input = $input.first().json;
const analysis = input.output;

if (!analysis || typeof analysis !== "object") {
  throw new Error("Claim Analyzer Agent returned invalid structured output.");
}

const demoData = $('Prepare Demo Data').first().json;

const totalBill = Number(analysis.total_bill_amount);
const estimatedCoverage = Number(analysis.estimated_coverage_amount);

const annualInterest = Number(demoData.annual_interest);
const months = Number(demoData.months);

if (
  !Number.isFinite(totalBill) ||
  !Number.isFinite(estimatedCoverage) ||
  !Number.isFinite(annualInterest) ||
  !Number.isFinite(months) ||
  totalBill <= 0 ||
  estimatedCoverage < 0 ||
  estimatedCoverage > totalBill ||
  annualInterest < 0 ||
  months <= 0
) {
  throw new Error("Invalid financial analysis data. Check Gemini output and Prepare Demo Data.");
}

const patientShare = totalBill - estimatedCoverage;
const monthlyRate = annualInterest / 100 / 12;

const emi = monthlyRate === 0
  ? patientShare / months
  : patientShare * monthlyRate *
    Math.pow(1 + monthlyRate, months) /
    (Math.pow(1 + monthlyRate, months) - 1);

return [{
  json: {
    ...analysis,
    financial_estimate: {
      total_bill_inr: totalBill,
      illustrative_coverage_inr: estimatedCoverage,
      illustrative_patient_share_inr: patientShare,
      annual_interest_percent: annualInterest,
      tenure_months: months,
      estimated_monthly_emi_inr: Math.round(emi),
      disclaimer: "Illustrative estimate only. Actual insurance coverage and financing are not approved or guaranteed."
    },
    review_status: "Human review required"
  }
}];
